"""Bundled private watch UI; no external resources or browser storage."""

import html

# Native HTML/CSS/JS line lengths remain readable.
# ruff: noqa: E501


def render_page(nonce):
    return PAGE.replace("@@NONCE@@", html.escape(nonce, quote=True))


PAGE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sniper · Your watches</title>
<style nonce="@@NONCE@@">
:root{color-scheme:dark;--bg:#101827;--panel:#182337;--line:#364761;--muted:#b6c4d8;--accent:#b7f2cf;--ink:#eef3ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1180px;padding:36px 24px 64px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:36px}.accent{color:var(--accent)}.form-actions{margin-top:20px}.brand{font-size:19px;letter-spacing:3px;font-weight:850}.pill{font-size:12px;border:1px solid var(--line);padding:7px 12px;border-radius:30px;color:var(--muted)}h1{font-size:clamp(32px,5vw,52px);letter-spacing:-2px;line-height:1.1;margin:0 0 14px}h2{font-size:21px;margin:0 0 12px}h3{margin:0;font-size:19px}p{margin:0 0 14px}.muted,small{color:var(--muted)}.intro{max-width:720px}.layout{display:grid;grid-template-columns:360px minmax(0,1fr);gap:24px;align-items:start;margin-top:24px}.panel,.card{border:1px solid var(--line);border-radius:16px;background:var(--panel);padding:22px}.panel{position:sticky;top:20px}label{display:block;margin:16px 0;font-weight:650;font-size:14px}input,select,button{font:inherit;border:1px solid #52634b;border-radius:9px;min-height:46px}input,select{display:block;width:100%;padding:11px;background:var(--bg);color:var(--ink);margin:6px 0}button{cursor:pointer;padding:10px 16px;background:var(--accent);color:#15200b;font-weight:750}button.secondary{color:var(--ink);background:transparent;border-color:var(--line)}button:disabled{opacity:.45;cursor:not-allowed}input:focus,select:focus,button:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}small{display:block;font-size:12px;font-weight:400;margin-top:6px}.row{display:flex;gap:12px}.row>*{flex:1;min-width:0}.check{display:flex;align-items:center;gap:10px}.check input{width:19px;min-height:19px;flex:none}.full{width:100%}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.toolbar h2{margin:0}.cards{display:grid;gap:14px}.card p{font-size:14px;margin:8px 0}.card-top{display:flex;justify-content:space-between;gap:12px;align-items:start}.price{font-size:23px;font-weight:750;letter-spacing:-.6px}.card a{color:var(--accent)}.card-actions{display:flex;gap:10px;margin-top:15px}.card-actions button{font-size:14px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid var(--line);padding-top:12px;margin-top:14px}.meta small{margin:0}.notice{padding:15px 18px;border-left:3px solid var(--accent);background:#1c3040;border-radius:6px;margin-top:22px;font-size:14px}.status{min-height:28px;margin:18px 0 0;font-size:14px}.error{color:#ffbcb3}.empty{padding:40px;text-align:center;color:var(--muted)}footer{margin-top:30px;color:var(--muted);font-size:12px}[hidden]{display:none!important}@media(max-width:800px){.layout{grid-template-columns:1fr}.panel{position:static}main{padding:24px 16px 40px}header{margin-bottom:28px}.card-top{flex-wrap:wrap}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s ease}}
</style></head><body><main>
<header><div class="brand">SNIPER<span class="accent">.</span></div><span class="pill">Private watchlist</span></header>
<div class="intro"><h1>Your next record starts here.</h1><p class="muted">Paste a Discogs release, set your item-price limit, and manage your watches in one place.</p></div>
<div class="notice"><strong>Availability leads, not verified listings.</strong> These watches track the release’s aggregate lowest item price and number for sale. They cannot filter media or sleeve grade, US sellers, shipping, tax or fees. Nothing here purchases a record.</div>
<p id="status" class="status" role="status" aria-live="polite">Loading your saved watches…</p>
<div class="layout"><section class="panel"><h2 id="form-title">Add a watch</h2><p class="muted" id="form-note">Save it here. No message to your assistant needed.</p>
<form id="watch-form"><label>Discogs release link or ID<input id="release" required maxlength="500" autocomplete="off" placeholder="https://www.discogs.com/release/…"><small>Use the exact release, not a master or sell/item link. No catalog request is made.</small></label>
<label>Record name <span class="muted">(optional)</span><input id="title" maxlength="120" autocomplete="off" placeholder="Artist · album · edition"><small>Leave blank to use the release ID. This label can appear in your existing private alerts.</small></label>
<div class="row"><label>Item-price limit<input id="price" required inputmode="decimal" pattern="[0-9]{1,7}([.][0-9]{1,2})?" maxlength="10" placeholder="40.00"><small>At or below this price, before shipping and fees.</small></label><label>Currency<select id="currency"><option>USD</option><option>GBP</option><option>EUR</option><option>CAD</option><option>AUD</option></select></label></div>
<label class="check"><input id="any-price" type="checkbox">Watch availability at any price</label>
<label class="check"><input id="enabled" type="checkbox" checked>Watch active</label>
<small>New watches use the existing private alert channel when monitoring is running. Price watches report initial under-limit availability and later under-limit price drops; any-price watches report availability and count increases. Existing alert preferences are preserved.</small>
<div class="row form-actions"><button id="save" type="submit" disabled>Save watch</button><button id="cancel" class="secondary" type="button" hidden>Cancel edit</button></div>
</form></section>
<section><div class="toolbar"><div><h2>Your watches <span id="count" class="muted"></span></h2><small id="monitor-status">Checking monitor status…</small></div><button id="refresh" type="button" class="secondary">Refresh</button></div>
<label>Find a saved watch<input id="search" type="search" placeholder="Search record name or release ID" autocomplete="off"></label><div id="watches" class="cards"></div></section></div>
<footer>Notification counts cover retained aggregate-watch history across saved prices, not a complete lifetime delivery record. The current-settings count starts again when a watch is changed. Saved to the existing Sniper watch store. Pausing keeps the watch so you can resume it later. No credentials, payment details, or new notification destinations are configured here. Unsaved edits stay only in this page.</footer>
</main><script nonce="@@NONCE@@">
'use strict';
const el = id => document.getElementById(id);
let state = null, busy = false, locked = true, editing = null, dirty = false;
function say(text, error=false) { el('status').textContent=text;el('status').classList.toggle('error',error); }
function controls() { el('save').disabled=busy||locked||!state;el('refresh').disabled=busy;el('cancel').disabled=busy;for(const node of el('watch-form').elements) { if(node.id!=='save'&&node.id!=='cancel') node.disabled=busy; }el('price').disabled=busy||el('any-price').checked;el('price').required=!el('any-price').checked;el('release').readOnly=editing!==null; for(const node of document.querySelectorAll('[data-action]')) node.disabled=busy||locked; }
async function request(path, options={}) { const response=await fetch('/watches/'+path,{credentials:'same-origin',cache:'no-store',...options});let data;try{data=await response.json();}catch{throw Error('The server response could not be verified. Refresh saved watches before trying again.');}if(!response.ok)throw Error(data.error||'The request could not be completed.');return data; }
function reset() { el('watch-form').reset();editing=null;dirty=false;el('form-title').textContent='Add a watch';el('form-note').textContent='Save it here. No message to your assistant needed.';el('save').textContent='Save watch';el('cancel').hidden=true;controls(); }
function load(w) { if(dirty&&!confirm('Replace your unsaved draft with this saved watch?'))return;editing={id:w.release_id,revision:w.revision};el('release').value=String(w.release_id);el('title').value=w.public_title;el('price').value=w.item_price_ceiling||'';el('currency').value=w.currency;el('any-price').checked=w.any_price;el('enabled').checked=w.enabled;dirty=false;el('form-title').textContent='Edit watch';el('form-note').textContent='Changes apply only to this release. To change the release, add a new watch.';el('save').textContent='Save changes';el('cancel').hidden=false;controls();el('title').focus(); }
function node(tag,text,cls) { const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n; }
function render() { const root=el('watches');root.replaceChildren();if(!state)return;el('count').textContent='('+state.watches.filter(w=>w.enabled).length+' active · '+state.watches.filter(w=>!w.enabled).length+' paused)';el('monitor-status').textContent=state.monitor_enabled?'Monitor enabled · latest successful checks below':'Monitor paused · saving watches will not start it';const query=el('search').value.trim().toLowerCase();const list=state.watches.filter(w=>(w.public_title+' '+w.release_id).toLowerCase().includes(query));if(!list.length)root.append(node('p',state.watches.length?'No watches match your search.':'No watches yet. Add your first release on the left.','empty'));
for(const w of list){const card=node('article',undefined,'card');const top=node('div',undefined,'card-top');const title=node('div');title.append(node('h3',w.public_title));const a=node('a','Release '+w.release_id);a.href='https://www.discogs.com/release/'+w.release_id;a.target='_blank';a.rel='noopener noreferrer';title.append(a);top.append(title,node('span',w.enabled?'Active':'Paused','pill'));card.append(top,node('p',w.any_price?'Any item price':w.currency+' '+w.item_price_ceiling+' or less','price'));const meta=node('div',undefined,'meta');const low=node('div');low.append(node('small','Latest aggregate minimum'),node('div',w.lowest_item_price?w.currency+' '+w.lowest_item_price:'Unknown'));const count=node('div');count.append(node('small','Aggregate copies for sale'),node('div',w.count===null?'Unknown':String(w.count)));meta.append(low,count);const notifications=node('div');notifications.append(node('small','Recorded notifications'),node('div',String(w.notifications.accepted)));const current=node('div');current.append(node('small','With current watch settings'),node('div',String(w.notifications.accepted_current_revision)));meta.append(notifications,current);card.append(meta);card.append(node('small','Counts are accepted by the notification service, not confirmed phone delivery.'));const pending=w.notifications.pending,flight=w.notifications.in_flight,uncertain=w.notifications.uncertain;if(pending||flight||uncertain)card.append(node('small',pending+' queued · '+flight+' in progress · '+uncertain+' uncertain (not counted above)'));const checked=w.last_success?new Date(w.last_success*1000).toLocaleString():'No successful check yet';card.append(node('small','Last successful check: '+checked));card.append(node('small','Alert preferences: '+[w.alert_initial_low?'initial availability':null,w.alert_price_drops?'price drops':null,w.alert_count_increases?'count increases':null].filter(Boolean).join(', ')));const actions=node('div',undefined,'card-actions');const edit=node('button','Edit','secondary');edit.type='button';edit.dataset.action='edit';edit.onclick=()=>load(w);const toggle=node('button',w.enabled?'Pause':'Resume','secondary');toggle.type='button';toggle.dataset.action='toggle';toggle.onclick=()=>save({release:String(w.release_id),title:w.public_title,currency:w.currency,price:w.item_price_ceiling,any_price:w.any_price,enabled:!w.enabled,revision:w.revision},false);actions.append(edit,toggle);card.append(actions);root.append(card);}controls(); }
async function refresh(announce=true) { if(busy)return;busy=true;controls();try{const next=await request('state');state=next;locked=false;render();if(announce)say('Saved watches refreshed. Your draft was kept.');}catch(e){locked=true;say(e.message,true);}finally{busy=false;controls();} }
async function save(fields, clearDraft) { if(busy||locked)return;busy=true;controls();say('Saving watch…');let confirmed=false;try{await request('save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,csrf:state.csrf})});confirmed=true;locked=true;if(clearDraft)reset();say('Watch saved. Refreshing saved watches…');}catch(e){locked=true;say(e.message+' Your draft was kept. Refresh saved watches to check whether it saved before retrying. No automatic retry was made.',true);}finally{busy=false;controls();}if(confirmed){await refresh(false);if(locked)say('Watch saved. '+el('status').textContent,true);else say(fields.enabled?'Watch saved. The existing monitor will pick it up while enabled.':'Watch paused. You can resume it here later.');} }
el('watch-form').addEventListener('submit',event=>{event.preventDefault();const release=el('release').value.trim();const revision=editing?editing.revision:0;save({release,title:el('title').value.trim(),currency:el('currency').value,price:el('any-price').checked?null:el('price').value.trim(),any_price:el('any-price').checked,enabled:el('enabled').checked,revision},true);});
el('watch-form').addEventListener('input',()=>{dirty=true;controls();});el('any-price').addEventListener('change',controls);el('search').addEventListener('input',render);el('refresh').onclick=()=>refresh();el('cancel').onclick=()=>{if(!dirty||confirm('Discard your unsaved changes?'))reset();};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});refresh(false);
</script></body></html>"""
